boolean is_user_trusted(def ctx, def users) {
  if (ctx?._security?.username == null) {
    return false;
  }

  def user = null;
  for (def item : users) {
    if (item?.username == ctx._security.username) {
      user = item;
      break;
    }
  }

  if (user == null || user?.realm == null || ctx?._security?.realm?.name == null) {
    return false;
  }

  if (ctx._security.realm.name != user.realm) {
    return false;
  }

  return true;
}

String verified(def ctx, def params) {
  // No agent.id field to validate.
  if (ctx?.agent?.id == null) {
    return "missing";
  }

  // Check auth metadata from API key.
  if (ctx?._security?.authentication_type == null
      // Agents only use API keys.
      || ctx._security.authentication_type != 'API_KEY'
      // Verify the API key owner before trusting any metadata it contains.
      || !is_user_trusted(ctx, params.trusted_users)
      // Verify the API key has metadata indicating the assigned agent ID.
      || ctx?._security?.api_key?.metadata?.agent_id == null) {
    return "auth_metadata_missing";
  }

  // The API key can only be used represent the agent.id it was issued to.
  if (ctx._security.api_key.metadata.agent_id != ctx.agent.id) {
    // Potential masquerade attempt.
    return "mismatch";
  }

  return "verified";
}

if (ctx?.event == null) {
  ctx.event = [:];
}

ctx.event.agent_id_status = verified(ctx, params);

Map dynamic_templates = new HashMap();
for (entry in ctx._metric_descriptions.entrySet()) {
  String name = entry.getKey();
  Map description = entry.getValue();
  String metric_type = description.type;
  if (metric_type == "histogram") {
    dynamic_templates[name] = "histogram_metrics";
  } else if (metric_type == "summary") {
    dynamic_templates[name] = "summary_metrics";
  } else {
    dynamic_templates[name] = "double_metrics";
  }
}
ctx._dynamic_templates = dynamic_templates;
ctx.remove("_metric_descriptions");

Map dynamic_templates = new HashMap();
for (sample in ctx.metricset.samples) {
  String name = sample.name;
  String metric_type = sample.type;
  if (metric_type == "histogram") {
    dynamic_templates[name] = "histogram_metrics";
    ctx.put(name, ["values": sample.values, "counts": sample.counts]);
  } else if (metric_type == "summary") {
    dynamic_templates[name] = "summary_metrics";
    ctx.put(name, ["value_count": sample.value_count, "sum": sample.sum]);
  } else {
    dynamic_templates[name] = "double_metrics";
    ctx.put(name, sample.value);
  }
}
ctx._dynamic_templates = dynamic_templates;
ctx.metricset.remove("samples");

def eventDuration = ctx.event?.duration ?: 0;
def rootObjectName = ctx.processor?.event;
def rootObject = ctx[rootObjectName];
if (rootObject == null) {
  rootObject = [:];
  ctx[rootObjectName] = rootObject;
}
rootObject.duration = ["us": (long)(eventDuration/1000)];

